pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { 
        c = new PrivatePool(address(this), address(this), address(this)); 
    }
    function testRegression_property() public {
        c.initialize(
            address(0),
            address(1),
            1000 ether,
            10 ether,
            0,
            0,
            bytes32(0),
            false,
            false
        );

        assertTrue(c.nft() == address(1), "nft should be set to address(1)");
    }
}
